// Use the genuine exported AppIcon rendition, never a recolored substitute.
(() => {
  const root = document.documentElement;
  const system = matchMedia('(prefers-color-scheme: dark)');
  function syncIcons() {
    const dark = root.dataset.theme ? root.dataset.theme === 'dark' : system.matches;
    document.querySelectorAll('[data-app-icon]').forEach(element => {
      const path = dark ? element.dataset.iconDark : element.dataset.iconLight;
      const attribute = element.tagName === 'LINK' ? 'href' : 'src';
      if (element.getAttribute(attribute) !== path) element.setAttribute(attribute, path);
    });
  }
  new MutationObserver(syncIcons).observe(root, {attributes: true, attributeFilter: ['data-theme']});
  system.addEventListener('change', syncIcons);
  syncIcons();
})();

:root {
  color-scheme: light;
  --bg: #f5f5f7;
  --surface: #fff;
  --ink: #1d1d1f;
  --muted: #626268;
  --line: rgba(29,29,31,.14);
  --blue: #0066cc;
  --notice: #eeeef0;
  --rail: 1160px;
}
html[data-theme="dark"] {
  color-scheme: dark;
  --bg: #000;
  --surface: #161617;
  --ink: #f5f5f7;
  --muted: #aaaab0;
  --line: rgba(255,255,255,.18);
  --blue: #2997ff;
  --notice: #1c1c1e;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 100px; }
body { margin: 0; background: var(--bg); color: var(--ink); font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",Arial,sans-serif; -webkit-font-smoothing: antialiased; line-height: 1.6; }
a { color: var(--blue); text-underline-offset: .2em; }
a:hover { text-decoration: underline; }
a:focus-visible, select:focus-visible, summary:focus-visible { outline: 3px solid var(--blue); outline-offset: 4px; border-radius: 4px; }
button,select { font: inherit; }
h1,h2,h3,p { margin: 0; }
h1,h2,h3 { line-height: 1.15; text-wrap: balance; }
h1,h2 { font-family: -apple-system,BlinkMacSystemFont,"SF Pro Display","Helvetica Neue",Arial,sans-serif; }
.rail { width: min(100% - 48px,var(--rail)); margin-inline: auto; }
.sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }
.skip-link { position: fixed; top: 10px; left: 16px; z-index: 100; padding: 10px 18px; background: var(--surface); transform: translateY(-150%); }
.skip-link:focus { transform: none; }
.nav { position: sticky; top: 0; z-index: 20; background: var(--bg); border-bottom: 1px solid var(--line); }
.nav-inner { min-height: 74px; display: flex; justify-content: space-between; align-items: center; gap: 20px; }
.brand { display: inline-flex; align-items: center; gap: 10px; color: var(--ink); font-size: 21px; font-weight: 650; text-decoration: none; flex-shrink: 0; }
.brand-art { width: 42px; height: 42px; display: grid; place-items: center; }
.brand img { display: block; object-fit: contain; }
.brand .plane-dark { display: none; }
[data-theme="dark"] .brand .plane-light { display: none; }
[data-theme="dark"] .brand .plane-dark { display: block; }
.nav-links { display: flex; gap: 24px; flex-wrap: wrap; }
.nav-links a, .footer nav a { color: var(--muted); text-decoration: none; font-size: 14px; }
.nav-links a:hover,.footer nav a:hover { color: var(--ink); text-decoration: underline; }
.nav-controls { display: flex; gap: 8px; flex-shrink: 0; }
.nav-controls select { min-height: 44px; max-width: 145px; background: var(--surface); border: 1px solid var(--line); border-radius: 9px; color: var(--ink); font-size: 14px; padding: 8px 24px 8px 10px; }
.draft-notice { background: var(--notice); padding: 14px 0; }
.draft-notice .rail { display: flex; gap: 18px; align-items: baseline; font-size: 13px; line-height: 1.5; }
.draft-notice strong { flex-shrink: 0; }
.draft-notice p { color: var(--muted); }
.eyebrow { font-size: 12px; line-height: 1.5; font-weight: 650; color: var(--muted); letter-spacing: .07em; margin-bottom: 22px; }
.hero { padding-block: 76px 104px; display: grid; grid-template-columns: minmax(0,1.3fr) minmax(0,.85fr); gap: 76px; align-items: center; }
h1 { font-size: clamp(46px,5.6vw,76px); line-height: 1.03; letter-spacing: -.055em; max-width: 11.2em; }
h1 > span { display: block; }
html[lang="zh-Hans"] h1 { line-height: 1.16; letter-spacing: -.035em; max-width: 8.5em; }
.lead { font-size: 22px; line-height: 1.6; color: var(--muted); margin-top: 28px; max-width: 29em; }
.actions { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; margin-top: 30px; }
.button { display: inline-flex; align-items: center; justify-content: center; min-height: 46px; padding: 10px 21px; border-radius: 999px; text-decoration: none; font-size: 15px; font-weight: 600; }
.button.primary { color: var(--surface); background: var(--ink); }
[data-theme="dark"] .button.primary { background: #f5f5f7; color: #000; }
.button:hover { text-decoration: none; opacity: .9; }
.text-link { font-size: 15px; text-decoration: none; font-weight: 550; }
.availability { color: var(--muted); font-size: 13px; margin-top: 30px; }
.store-status { color: var(--muted); font-size: 13px; margin-top: 4px; }
.plan-example { padding: 30px; border: 1px solid var(--line); border-radius: 24px; background: var(--surface); }
.plan-example .eyebrow { margin-bottom: 14px; }
.plan-example h2 { font-size: 28px; line-height: 1.2; letter-spacing: -.03em; }
.example-timeline { list-style: none; padding: 0; margin: 28px 0 22px; }
.example-timeline li { display: grid; grid-template-columns: 48px 1fr; gap: 15px; padding: 18px 0; border-top: 1px solid var(--line); }
.example-timeline time { font-size: 13px; line-height: 1.6; color: var(--muted); font-variant-numeric: tabular-nums; }
.example-timeline h3 { font-size: 16px; line-height: 1.45; }
.example-timeline p { margin-top: 5px; font-size: 13px; color: var(--muted); }
.example-stay { padding: 15px 0 0; border-top: 1px solid var(--line); }
.example-stay .stay-label { font-size: 14px; font-weight: 650; }
.example-stay p+p { font-size: 13px; color: var(--muted); margin-top: 4px; }
.caption { font-size: 11px; color: var(--muted); margin-top: 22px; }
.section { padding-block: 96px; border-top: 1px solid var(--line); }
.section h2 { font-size: clamp(32px,3.8vw,49px); line-height: 1.14; letter-spacing: -.04em; max-width: 16em; }
.section-intro { font-size: 19px; line-height: 1.7; color: var(--muted); max-width: 36em; margin-top: 22px; }
.features-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 44px; margin-top: 56px; }
.features-grid article { border-top: 1px solid var(--line); padding-top: 25px; }
.features-grid .eyebrow { margin-bottom: 18px; }
.features-grid h3 { font-size: 26px; line-height: 1.22; letter-spacing: -.025em; }
.features-grid h3+p { color: var(--muted); font-size: 16px; line-height: 1.8; margin-top: 18px; }
.surface { background: var(--surface); border-top: 1px solid var(--line); }
.surface .section { border-top: 0; }
.how-section,.control-section,.questions-section,.support-section { display: grid; grid-template-columns: minmax(0,.82fr) minmax(0,1.18fr); gap: 88px; }
.steps-list { list-style: none; padding: 0; margin: 0; }
.steps-list li { display: grid; grid-template-columns: 35px 1fr; gap: 22px; border-top: 1px solid var(--line); padding-block: 25px; }
.steps-list li:first-child { padding-top: 4px; border-top: 0; }
.step-number { color: var(--blue); font-size: 17px; font-weight: 650; font-variant-numeric: tabular-nums; }
.steps-list h3 { font-size: 22px; line-height: 1.3; }
.steps-list p { color: var(--muted); margin-top: 12px; font-size: 16px; line-height: 1.8; }
.control-section .section-intro,.support-section .section-intro { margin-top: 0; }
.control-section .text-link { display: inline-block; margin-top: 24px; }
.faq-list { border-top: 1px solid var(--line); }
.faq-list details { border-bottom: 1px solid var(--line); padding-block: 20px; }
summary { font-size: 17px; font-weight: 600; cursor: pointer; line-height: 1.55; }
summary::marker { color: var(--blue); }
details p { color: var(--muted); font-size: 16px; line-height: 1.8; margin-top: 15px; }
.contact-email { display: inline-block; font-size: clamp(18px,2.2vw,25px); font-weight: 550; margin-top: 22px; overflow-wrap: anywhere; }
.support-note { color: var(--muted); font-size: 14px; margin-top: 20px; line-height: 1.8; max-width: 40em; }
.privacy-intro { max-width: 760px; }
.policy-date { font-size: 14px; color: var(--muted); margin-top: 20px; }
.privacy-layout { margin-top: 58px; display: grid; grid-template-columns: 270px minmax(0,1fr); gap: 64px; align-items: start; }
.policy-toc { position: sticky; top: 110px; }
.policy-toc h3 { font-size: 16px; }
.policy-toc ol { padding: 0; list-style: none; margin: 17px 0 0; }
.policy-toc li { margin-block: 10px; }
.policy-toc a { color: var(--muted); text-decoration: none; font-size: 13px; }
.policy-toc a:hover { color: var(--blue); text-decoration: underline; }
.policy-body { max-width: 750px; font-size: 16px; line-height: 1.9; overflow-wrap: anywhere; }
.policy-body section { margin-bottom: 36px; }
.policy-body h3 { font-size: 22px; line-height: 1.4; letter-spacing: -.015em; }
.policy-body h3+p,.policy-body p+p { margin-top: 15px; }
.policy-body p { color: var(--muted); }
.policy-references { border-top: 1px solid var(--line); padding-top: 28px; }
.policy-references h3 { font-size: 18px; }
.policy-references ul { margin-top: 16px; padding-left: 22px; }
.policy-references li { margin-block: 7px; }
.review-notes { background: var(--surface); padding: 30px; border: 1px solid var(--line); border-radius: 18px; margin-top: 42px; }
.review-notes h3 { font-size: 20px; }
.review-notes ul { padding-left: 22px; color: var(--muted); font-size: 15px; margin-bottom: 0; }
.review-notes li+li { margin-top: 14px; }
.footer { border-top: 1px solid var(--line); padding-block: 32px; color: var(--muted); font-size: 12px; }
.footer-top { display: flex; justify-content: space-between; gap: 22px; flex-wrap: wrap; }
.footer nav { display: flex; gap: 24px; flex-wrap: wrap; }
.footer nav a { font-size: 12px; }
.static-versions { margin-top: 24px; }
.static-versions p { margin-bottom: 7px; }
.language-status:empty { display: none; }
.language-status { margin-top: 14px; }
@media (prefers-color-scheme: dark) {
  html:not([data-theme]) { color-scheme: dark; --bg: #000; --surface: #161617; --ink: #f5f5f7; --muted: #aaaab0; --line: rgba(255,255,255,.18); --blue: #2997ff; --notice: #1c1c1e; }
  html:not([data-theme]) .brand .plane-light { display: none; }
  html:not([data-theme]) .brand .plane-dark { display: block; }
  html:not([data-theme]) .button.primary { background: #f5f5f7; color: #000; }
}
@media (max-width: 980px) {
  .nav-inner { gap: 16px; flex-wrap: wrap; padding-block: 12px; }
  .nav-links { order: 3; width: 100%; justify-content: center; gap: 28px; }
  .hero { gap: 36px; padding-block: 62px 78px; }
  h1 { font-size: 55px; }
  .lead { font-size: 19px; }
  .how-section,.control-section,.questions-section,.support-section { gap: 40px; }
  .features-grid { gap: 26px; }
  .privacy-layout { grid-template-columns: 220px minmax(0,1fr); gap: 35px; }
  .policy-toc { top: 150px; }
  html { scroll-padding-top: 160px; }
}
@media (max-width: 720px) {
  .rail { width: min(100% - 40px,var(--rail)); }
  .draft-notice .rail { display: block; }
  .draft-notice strong { display: block; margin-bottom: 4px; }
  .hero { grid-template-columns: 1fr; gap: 40px; padding-block: 48px 62px; }
  h1 { font-size: clamp(43px,9vw,60px); max-width: 12em; }
  html[lang="zh-Hans"] h1 { max-width: 8em; }
  .lead { font-size: 19px; }
  .plan-example { max-width: 560px; padding: 26px; }
  .section { padding-block: 64px; }
  .section h2 { font-size: 35px; }
  .features-grid { grid-template-columns: 1fr; gap: 34px; margin-top: 38px; }
  .features-grid article { max-width: 36em; }
  .how-section,.control-section,.questions-section,.support-section { grid-template-columns: 1fr; gap: 32px; }
  .section-intro { font-size: 18px; }
  .privacy-layout { grid-template-columns: 1fr; gap: 36px; margin-top: 34px; }
  .policy-toc { position: static; border-bottom: 1px solid var(--line); padding-bottom: 22px; }
  .policy-toc ol { columns: 2; column-gap: 24px; }
  .policy-toc li { break-inside: avoid; }
  .policy-body { font-size: 16px; }
  .review-notes { padding: 23px; }
}
@media (max-width: 430px) {
  .rail { width: calc(100% - 32px); }
  .brand { font-size: 19px; gap: 5px; }
  .brand-art { width: 35px; }
  .nav-controls { gap: 5px; }
  .nav-controls select { max-width: 108px; font-size: 12px; padding-left: 7px; padding-right: 15px; }
  .nav-links { gap: 14px; }
  .nav-links a { font-size: 12px; }
  .actions { gap: 18px; }
  .policy-toc ol { columns: 1; }
  .plan-example { padding: 23px; }
}
@media (max-width: 360px) {
  .nav-inner { justify-content: center; }
  .nav-controls { width: 100%; justify-content: center; }
  .nav-links { gap: 12px; }
  html[lang="zh-Hans"] h1 { font-size: 36px; text-wrap: pretty; }
  html { scroll-padding-top: 220px; }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
@media print {
  .nav,.actions,.policy-toc,.footer,.skip-link { display: none; }
  .rail { width: 100%; }
  .section,.hero { padding-block: 22px; }
  .privacy-layout { display: block; }
  .policy-body { max-width: none; }
  .policy-body section { break-inside: avoid; }
  :root,html[data-theme="dark"] { --bg: #fff; --surface: #fff; --ink: #111; --muted: #333; --line: #ddd; --blue: #111; --notice: #fff; }
}

/* Intentional media stages. Replace only after UI acceptance and LaunchCanvas export. */
.screenshot-slot { margin:0; min-width:0; aspect-ratio:4/5; display:grid; place-items:center; padding:32px; background:linear-gradient(145deg,var(--surface),var(--bg)); border:1px solid var(--line); border-radius:28px; text-align:center; overflow:hidden; }
.screenshot-slot-inner strong { display:block; font-size:36px; letter-spacing:-.04em; margin:20px 0; }
.screenshot-slot p { font-size:14px; color:var(--muted); max-width:24em; }
.screenshot-slot-small { margin-top:30px; aspect-ratio:4/3; padding:20px; color:var(--muted); font-size:12px; }

(() => {
  const root = document.documentElement;
  const language = document.getElementById("tx-language");
  const theme = document.getElementById("tx-theme");
  const status = document.getElementById("tx-language-status");
  const systemTheme = window.matchMedia("(prefers-color-scheme: dark)");
  const origin = "https://werd-portfolio.eric-dai.chatgpt.site";
  const at = (copy, key) => key.split(".").reduce((value, part) => value?.[part], copy);
  let languageRequest;
  let copy;

  function readPreference(key) {
    try { return localStorage.getItem(key); } catch { return null; }
  }
  function storePreference(key, value) {
    try {
      if (value === null) localStorage.removeItem(key);
      else localStorage.setItem(key, value);
    } catch { /* Static content and controls still work when storage is unavailable. */ }
  }
  function requestedLocale() {
    const query = new URLSearchParams(location.search).get("lang");
    if (query) return /^(zh-hans|zh-cn)$/i.test(query) ? "zh-Hans" : "en-US";
    if (location.protocol === "file:") return root.dataset.pageLocale;
    const preference = readPreference("travelx-language");
    return ["en-US", "zh-Hans"].includes(preference) ? preference : root.dataset.pageLocale;
  }
  function updateTheme() {
    const selected = theme.value;
    root.dataset.theme = selected === "system" ? (systemTheme.matches ? "dark" : "light") : selected;
  }
  const storedTheme = readPreference("werd-theme");
  theme.value = ["light", "dark"].includes(storedTheme) ? storedTheme : "system";
  updateTheme();
  theme.addEventListener("change", () => {
    storePreference("werd-theme", theme.value === "system" ? null : theme.value);
    updateTheme();
  });
  systemTheme.addEventListener("change", () => { if (theme.value === "system") updateTheme(); });

  function syncLinks(locale) {
    document.getElementById("tx-home").href = `index.html?lang=${locale}`;
    document.getElementById("tx-canonical").href = `${origin}/travelx?lang=${locale}`;
    document.getElementById("tx-og-url").content = `${origin}/travelx?lang=${locale}`;
    document.querySelectorAll("[data-static-locale]").forEach(link => {
      const target = new URL(link.getAttribute("href"), location.href);
      target.hash = location.hash;
      link.href = target.href;
    });
  }

  async function applyLanguage(locale, chosen = false) {
    languageRequest?.abort();
    if (location.protocol === "file:" && locale !== root.lang) {
      if (chosen) storePreference("travelx-language", locale);
      const filename = locale === "zh-Hans" ? "travelx-zh-Hans.html" : "travelx.html";
      const target = new URL(filename, location.href);
      target.searchParams.set("lang", locale);
      target.hash = location.hash;
      location.href = target.href;
      return;
    }
    if (locale !== root.lang) {
      const controller = new AbortController();
      languageRequest = controller;
      try {
        const response = await fetch(new URL(`i18n/travelx/${locale}.json`, location.href), { signal: controller.signal });
        if (!response.ok) throw new Error("Language unavailable");
        const next = await response.json();
        if (next.locale !== locale) throw new Error("Wrong language");
        const textNodes = Array.from(document.querySelectorAll("[data-tx]"));
        const metaNodes = Array.from(document.querySelectorAll("[data-tx-meta]"));
        const strings = textNodes.map(node => at(next, node.dataset.tx));
        const metadata = metaNodes.map(node => at(next, node.dataset.txMeta));
        if (![...strings, ...metadata].every(value => typeof value === "string")) throw new Error("Incomplete language");
        if (controller.signal.aborted) return;
        textNodes.forEach((node, i) => { node.textContent = strings[i]; });
        metaNodes.forEach((node, i) => { node.content = metadata[i]; });
        root.lang = locale;
        copy = next;
        // Preserve a support/policy deep link when translated sections change height.
        if (location.hash) {
          let id;
          try { id = decodeURIComponent(location.hash.slice(1)); } catch { id = null; }
          if (id) document.getElementById(id)?.scrollIntoView({ behavior: "instant", block: "start" });
        }
      } catch (error) {
        if (error.name === "AbortError") return;
        language.value = root.lang;
        status.textContent = copy?.footer.languageError || (root.lang === "zh-Hans" ? "语言暂时未能加载，请使用页脚的语言链接。" : "The language could not be loaded. Use the language links in the footer.");
        return;
      }
    }
    language.value = locale;
    syncLinks(locale);
    if (chosen) {
      const target = new URL(location.href);
      target.searchParams.set("lang", locale);
      history.replaceState(null, "", target.href);
      storePreference("travelx-language", locale);
      status.textContent = copy?.footer.languageStatus || (locale === "zh-Hans" ? "语言已切换。" : "Language updated.");
    }
  }
  language.addEventListener("change", () => applyLanguage(language.value, true));
  window.addEventListener("popstate", () => applyLanguage(requestedLocale()));
  window.addEventListener("hashchange", () => syncLinks(root.lang));
  applyLanguage(requestedLocale());
})();

